let declaration_pin = "73d45fad612c18d7e7204027a5e2f829c1ac34a2ad3313ab65cc88f9a10909c8"
let operation fixture = Json.string (get "operation" fixture)
let run ?parent ?(request_id="producer-protocol-literal") fixture =
  K.handle ?parent ~executable:Protocol.Core ~request_id ~operation:(operation fixture) (get "payload" fixture)
let with_payload fixture payload = set "payload" payload fixture
let baseline = List.hd fixtures
let defaults = get "default_limits" (get "synthetic_generation" expected_profiles)
let reduction fixture key value = with_payload fixture (set "limits" (set key value defaults) (get "payload" fixture))
let equal message left right = require (Canonical.encode left=Canonical.encode right) message
let request operation payload = {Protocol.request_id="producer-protocol-literal";operation;payload}
let literals () =
  require (List.length fixtures=23) "Original producer literal census differs";
  require (Canonical.fingerprint expected_profiles=declaration_pin) "Immutable producer declaration pin changed";
  equal "Native capability declaration/resources differ" (Json.Object K.profiles) expected_profiles;
  List.iter (fun fixture ->
    match get "error_code" fixture with
    | Json.String code -> rejected code (fun () -> run fixture)
    | Json.Null -> equal (Json.string (get "name" fixture) ^ ": complete record, error, identity or scope differs")
        (run fixture) (get "expected" fixture)
    | _ -> failwith "Invalid literal error expectation") fixtures;
  let call role operation payload = P.handle role (request operation payload) in
  let capabilities = match call Protocol.Core "capabilities" (Json.Object []) with
    | Protocol.Ok,Some value,[] -> value | _ -> failwith "Core capabilities unavailable" in
  List.iter (fun (key,value) -> equal "Producer profile missing" value (get key (get "profiles" capabilities))) K.profiles;
  List.iter (fun operation -> match call Protocol.Verify operation (get "payload" baseline) with
    | Protocol.Unsupported,None,[diagnostic] -> require (diagnostic.code="unsupported_operation") "Wrong verifier rejection"
    | _ -> failwith "Verifier granted producer access") K.operations;
  require (call Protocol.Verify "capabilities" (Json.Object []) =
    Base.handle Protocol.Verify (request "capabilities" (Json.Object []))) "Verifier acquired a producer profile";
  match call Protocol.Core (operation baseline) (get "payload" baseline) with
  | Protocol.Ok,Some result,[] -> equal "Dispatch changed full producer result" result (get "expected" baseline)
  | _ -> failwith "Core dispatch failed"
let malformed () =
  let payload = get "payload" baseline in
  let call payload = run (with_payload baseline payload) in
  rejected "missing_field" (fun () -> call (Json.Object (List.remove_assoc "profile" (Json.object_fields payload))));
  rejected "unknown_field" (fun () -> call (set "producer_override" (str "untrusted") payload));
  rejected "duplicate_key" (fun () -> call (Json.Object (("profile",get "profile" payload)::Json.object_fields payload)));
  rejected "synthetic_producer_profile" (fun () -> call (set "profile" (str "biocompiler.core.synthetic_selection.v1") payload));
  rejected "invalid_type" (fun () -> call (set "profile" (Json.Bool true) payload));
  List.iter (fun value -> rejected "synthetic_producer_limits" (fun () -> call (set "limits" value payload)))
    [Json.Bool true;Json.Float 1.;Json.Array []];
  rejected "missing_field" (fun () -> call (set "limits" (Json.Object []) payload));
  rejected "unknown_field" (fun () -> call (set "limits" (set "extra" Json.Null defaults) payload));
  List.iter (fun (key,ceiling) ->
    List.iter (fun value -> rejected "synthetic_producer_limits" (fun () -> run (reduction baseline key value)))
      [Json.Bool true;Json.Float 1.;Json.Null;Json.int 0;Json.int (-1);Json.int (ceiling+1);Json.Int (Z.pow (Z.of_int 10) 100)])
    ["max_work",50_000_000;"max_monitor_items",100_000;"max_request_bytes",Limits.max_request_bytes;
     "max_report_bytes",Limits.max_response_bytes;"max_report_nodes",Limits.max_json_nodes];
  let selected = List.find (fun fixture -> operation fixture="select-synthetic") fixtures in
  rejected "invalid_type" (fun () -> run (with_payload selected (set "until" (Json.Bool false) (get "payload" selected))));
  rejected "synthetic_selection" (fun () -> run (with_payload selected (set "until" (Json.int (-1)) (get "payload" selected))));
  rejected "invalid_type" (fun () -> call (set "request" Json.Null payload))
let identities () =
  let normal = run baseline in
  let explicit = run (with_payload baseline (set "limits" defaults (get "payload" baseline))) in
  equal "Explicit default limits changed complete proposal" (get "record" normal) (get "record" explicit);
  equal "Explicit limits changed typed authority" (get "authority_identities" normal) (get "authority_identities" explicit);
  require (not (Json.equal (get "supplied_authority_fingerprint" normal) (get "supplied_authority_fingerprint" explicit)))
    "Raw null/default limit distinction was erased";
  let errors = List.filter (fun fixture -> match get "expected" fixture with
    | Json.Null -> false | result -> get "generation_error" result <> Json.Null) fixtures in
  require (List.length errors=10) "Structured ordinary Unsupported census differs";
  List.iter (fun fixture -> let result = run fixture in
    require (get "record" result=Json.Null && get "record_fingerprint" result=Json.Null &&
      get "outcome" result=str "unsupported") "Ordinary Unsupported became a proposal";
    equal "Unsupported lost complete node/source/message" (get "generation_error" result)
      (get "generation_error" (get "expected" fixture))) errors
let resources () =
  let operation = operation baseline and payload = get "payload" baseline in
  let _,usage = K.handle_with_usage ~executable:Protocol.Core ~request_id:"producer-protocol-literal" ~operation payload in
  let parent maximum = W.create ~profile:"producer.literal.parent" ~error_code:"producer_parent_limit" ~maximum () in
  let exact = parent usage.work_charged in
  equal "Exact ancestor changed proposal" (run ~parent:exact baseline) (get "expected" baseline);
  require (W.remaining exact=0) "Framing/import/hash/production/publication escaped ancestor";
  let short = parent (usage.work_charged-1) in
  (match run ~parent:short baseline with
   | _ -> failwith "One-under ancestor returned a result"
   | exception Diagnostic.Error error -> require (error.code="producer_parent_limit" && W.is_exhaustion short error)
       "Resource exception lost its ancestor identity");
  List.iter (fun (key,code) -> rejected code (fun () -> run (reduction baseline key (Json.int 1))))
    ["max_work","synthetic_producer_work_limit";"max_request_bytes","realization_input_limit";
     "max_report_bytes","realization_report_limit";"max_report_nodes","realization_report_limit";
     "max_monitor_items","realization_monitor_limit"];
  List.iter (fun (key,maximum) ->
    let passes value = match run (reduction baseline key (Json.int value)) with
      | _ -> true | exception Diagnostic.Error error ->
          require (List.mem error.code ["realization_work_limit";"synthetic_producer_work_limit";
            "realization_input_limit";"realization_report_limit";"realization_monitor_limit"])
            ("Unexpected boundary diagnostic: " ^ error.code); false in
    let rec narrow low high = if high-low<=1 then high else
      let middle = low+(high-low)/2 in if passes middle then narrow low middle else narrow middle high in
    let threshold = narrow 1 maximum in
    require (passes threshold && not (passes (threshold-1))) ("Exact reduced limit boundary differs: " ^ key))
    ["max_work",50_000_000;"max_request_bytes",Limits.max_request_bytes;
     "max_report_bytes",Limits.max_response_bytes;"max_report_nodes",Limits.max_json_nodes;"max_monitor_items",100_000];
  let _,long = K.handle_with_usage ~executable:Protocol.Core ~request_id:(String.make 4096 'x') ~operation payload in
  require (long.work_charged>usage.work_charged && long.report_bytes>usage.report_bytes)
    "Actual request identity omitted from work/publication";
  rejected "string_limit" (fun () -> run ~request_id:(String.make (Limits.max_string_bytes+1) 'x') baseline);
  let rec cycle = Json.Array [cycle] in
  rejected "nesting_limit" (fun () -> run (with_payload baseline (set "request" cycle payload)));
  let rec spine = Json.Null :: spine in
  rejected "node_limit" (fun () -> run (with_payload baseline (set "request" (Json.Array spine) payload)));
  let rec fields = ("loop",Json.Null) :: fields in
  rejected "node_limit" (fun () -> run (with_payload baseline (set "request" (Json.Object fields) payload)));
  equal "Failure affected later operation" (run baseline) (get "expected" baseline)
let () =
  literals ();malformed ();identities ();resources ();
  print_endline "Synthetic producer literal records/errors, role separation, complete authority and shared resource boundaries passed"
